export interface DebounceOptions {
  leading?: boolean;
  trailing?: boolean;
}

export interface Debounced<A extends unknown[]> {
  (...args: A): void;
  cancel(): void;
  flush(): void;
  pending(): boolean;
}

export function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  waitMs: number,
  options: DebounceOptions = {},
): Debounced<A> {
  if (waitMs < 0 || !Number.isFinite(waitMs)) {
    throw new RangeError('waitMs must be a finite non-negative number');
  }

  const leading: boolean = options.leading ?? false;
  const trailing: boolean = options.trailing ?? true;

  let timerId: ReturnType<typeof setTimeout> | undefined;
  let lastArgs: A | undefined;
  let calledOnLeading: boolean = false;

  const debounced = ((...args: A): void => {
    lastArgs = args;

    if (timerId === undefined) {
      // New burst starts
      if (leading) {
        fn(...args);
        calledOnLeading = true;
      }
    } else if (leading && !calledOnLeading) {
      // Restart timer on subsequent calls in the burst
      // If leading is true but not yet called, this is a subsequent call
      // which shouldn't happen since we only enter this branch when timer is set
    }

    // Schedule trailing call if needed
    timerId = setTimeout(() => {
      if (trailing && !(leading && calledOnLeading)) {
        if (lastArgs) {
          fn(...lastArgs);
        }
      }
      calledOnLeading = false;
      timerId = undefined;
      lastArgs = undefined;
    }, waitMs) as ReturnType<typeof setTimeout>;
  }) as Debounced<A>;

  debounced.cancel = (): void => {
    if (timerId !== undefined) {
      clearTimeout(timerId);
      timerId = undefined;
    }
    calledOnLeading = false;
    lastArgs = undefined;
  };

  debounced.flush = (): void => {
    if (timerId !== undefined) {
      clearTimeout(timerId);
      timerId = undefined;

      if (trailing && !(leading && calledOnLeading)) {
        if (lastArgs) {
          fn(...lastArgs);
        }
      }
      calledOnLeading = false;
      lastArgs = undefined;
    }
  };

  debounced.pending = (): boolean => {
    return timerId !== undefined;
  };

  return debounced;
}
```

